// s: abertura do olho, de 1 (aberto) a perto de 0 (fechado)
export const LogoPiscando = ({ largura, s }: { largura: number; s: number }) => (
  <svg
    width={largura}
    height={(largura * 60) / 186}
    viewBox="0 0 186 60"
    fill="none"
    style={{ display: "block", overflow: "visible" }}
    dangerouslySetInnerHTML={{ __html: MIOLO.replaceAll("__S__", s.toFixed(3)).replaceAll("__H__", s > 0.55 ? "1" : "0").replaceAll("__B__", ((1 - s) * 0.45).toFixed(3)) }}
  />
);
